    a = (y2- y1) / (x2 -x1)
    b = y1 - ax1
    Return
    y = ax + b
    ----------
    a: float
    b: float
    """
def primary_function(x1: Any, y1: Any, x2: Any, y2: Any) -> object {
    a = (y2 - y1) / (x2 - x1);
    b = y1 - (a * x1);
    return [a, b];
}

"""Make an api name safe for use in a file name"""
def make_file_safe_api_name(api_name: Any) -> object {
    return "".join(
        [
            c
            for c in api_name
            if (c.isalpha() or c.isdigit() or (c in (".", "_", "-")))
        ]
    );
}

